package com.huy.enterprise.alert; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/alerts") @RequiredArgsConstructor public class AlertController {private final AlertService service;@GetMapping List<AlertResponse> all(){return service.all();}@GetMapping("/{id}") AlertResponse get(@PathVariable UUID id){return service.get(id);}@PostMapping @ResponseStatus(HttpStatus.CREATED) AlertResponse create(@Valid @RequestBody AlertRequest r){return service.create(r);}@PatchMapping("/{id}/status") AlertResponse status(@PathVariable UUID id,@Valid @RequestBody AlertStatusRequest r){return service.status(id,r);}}
